document.addEventListener('DOMContentLoaded', function () {
    document.querySelectorAll('.box-pricing-2 ul li').forEach(item => { item.addEventListener('click', function () { this.classList.toggle('selected'); }); }); function initializePopup() { const getQuoteLinks = document.querySelectorAll('.getQuote'); const orderPopup = document.querySelector('.order-popup'); const contactForm = document.querySelector('.contact-us-form'); const overlay = document.querySelector('.overlay'); const hiddenInput = document.getElementById('selected_package'); getQuoteLinks.forEach(link => { link.addEventListener('click', function (event) { event.preventDefault(); const packageName = this.getAttribute('data-package-name') || "غير محدد"; hiddenInput.value = packageName; orderPopup.style.display = 'block'; overlay.style.display = 'block'; }); }); overlay.addEventListener('click', function () { orderPopup.style.display = 'none'; overlay.style.display = 'none'; }); contactForm.addEventListener('click', function (event) { event.stopPropagation(); }); }
    initializePopup(); const form = document.getElementById('formContactPricing'); form.addEventListener('submit', function (e) {
        e.preventDefault(); const hiddenInput = document.getElementById('selected_package'); const selectedServices = []; document.querySelectorAll('.box-pricing-2 ul li.selected').forEach(li => { selectedServices.push(li.textContent.trim()); }); if (selectedServices.length > 0) { hiddenInput.value = 'خدمات مخصصة: ' + selectedServices.join(', '); }
        const formData = new FormData(form); fetch(form.action, { method: 'POST', body: formData }).then(response => response.json()).then(result => { if (result.status === "success") { document.querySelector('.order-popup').style.display = 'none'; document.querySelector('.overlay').style.display = 'none'; const popup = document.getElementById('overlay-pop'); popup.style.display = 'block'; setTimeout(() => { popup.style.display = 'none'; form.reset(); hiddenInput.value = "غير محدد"; }, 3000); } else { alert("حدث خطأ أثناء إرسال الطلب."); } }).catch(() => { alert("تعذر الاتصال بالخادم."); });
    });
});